#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker is a raw C++ pointer (UArenaScoreTracker* ScoreTracker = nullptr) without UPROPERTY, so Unreal's garbage collector can destroy the object it points to. After the first GC pass (log line 8: 'Collecting garbage: 412 objects purged' at 21:05.13), the pointer is dangling; the first goal at 21:05.27 dereferences it in UArenaScoreTracker::AddPoints() (ArenaScoreTracker.cpp:18), causing EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff. Fix: make it a UPROPERTY() TObjectPtr<UArenaScoreTracker> so GC keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is never cooked into the packaged build: DefaultGame.ini has bCookAll=False and only /Game/Maps/Arena is in MapsToCook plus /Game/Effects in DirectoriesToAlwaysCook, so the async/synchronous LoadObject in AArenaGameMode::BeginPlay fails (log lines 4-5: 'Couldn't find file for package /Game/Data/Palettes/DA_Primary'), Palette stays null and the HUD falls back to gray (log line 6). Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook (or set bCookAll=True) so the palette asset is packaged."
}
